package com.nypunya.assessment.entity;
import javax.persistence.*;
@Entity @Table(name="quiz_answers",uniqueConstraints=@UniqueConstraint(name="uk_answer_attempt_question",columnNames={"attempt_id","question_id"}),indexes=@Index(name="idx_answer_attempt",columnList="attempt_id"))
public class QuizAnswer { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="attempt_id",nullable=false) private Long attemptId; @Column(name="question_id",nullable=false) private Long questionId; @Column(name="selected_option_id") private Long selectedOptionId; @Column(name="is_correct") private Boolean correct; public Long getId(){return id;} public Long getAttemptId(){return attemptId;} public void setAttemptId(Long v){attemptId=v;} public Long getQuestionId(){return questionId;} public void setQuestionId(Long v){questionId=v;} public Long getSelectedOptionId(){return selectedOptionId;} public void setSelectedOptionId(Long v){selectedOptionId=v;} public Boolean getCorrect(){return correct;} public void setCorrect(Boolean v){correct=v;} }
